export { EvidenceScreen } from "./screens/EvidenceScreen";
import { Screen, Text } from "@/lib/ui";

export function EvidenceScreen() {
  return (
    <Screen>
      <Text variant="title">Evidence log</Text>
      <Text>Out-of-hours noise reports, with each log's hash anchored on Solana.</Text>
    </Screen>
  );
}
import { anchorInput, anchorOutput, verifyInput, verifyOutput } from "@kip/shared/evidence";
import { TRPCError } from "@trpc/server";
import { notImplemented, publicProcedure, router, userProcedure } from "../../trpc/init";
import { NightNotFoundError, NightStorageError } from "../night";
import { EvidenceChainError } from "./errors";
import { loadLive } from "./load";
import type { EvidenceService } from "./service";

function mapEvidenceError(error: unknown): never {
  if (error instanceof NightNotFoundError) {
    throw new TRPCError({ code: "NOT_FOUND", message: error.message });
  }
  if (error instanceof EvidenceChainError) {
    throw new TRPCError({ code: "BAD_GATEWAY", message: error.message });
  }
  if (error instanceof NightStorageError) {
    throw new TRPCError({ code: "INTERNAL_SERVER_ERROR", message: error.message });
  }
  throw error;
}

export function createEvidenceRouter(svc?: EvidenceService) {
  const service = async () => svc ?? (await loadLive()).liveEvidence;
  return router({
    anchor: userProcedure.input(anchorInput).mutation(async ({ ctx, input }) => {
      try {
        return anchorOutput.parse(await (await service()).anchor(ctx.userId, input.nightId));
      } catch (error) {
        mapEvidenceError(error);
      }
    }),
    verify: publicProcedure.input(verifyInput).query(async ({ input }) => {
      try {
        return verifyOutput.parse(await (await service()).verify(input.nightId));
      } catch (error) {
        mapEvidenceError(error);
      }
    }),
    // Council report: a later issue.
    report: userProcedure.input(anchorInput).query(() => notImplemented()),
  });
}

export const evidenceRouter = createEvidenceRouter();
/** Canonical JSON: object keys sorted, no whitespace, so equal data always gives equal bytes. */
export function canonicalJson(value: unknown): string {
  if (value === null) return "null";
  switch (typeof value) {
    case "string":
    case "boolean":
      return JSON.stringify(value);
    case "number":
      if (!Number.isFinite(value)) throw new Error("Cannot serialise a non-finite number");
      return JSON.stringify(value);
    case "object": {
      if (Array.isArray(value)) {
        return `[${value.map((item) => canonicalJson(item ?? null)).join(",")}]`;
      }
      const entries = Object.entries(value as Record<string, unknown>)
        .filter(([, item]) => item !== undefined)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`);
      return `{${entries.join(",")}}`;
    }
    default:
      throw new Error(`Cannot serialise a ${typeof value}`);
  }
}

const MEMO_PREFIX = "kip:v1:";
const HASH_HEX = /^[0-9a-f]{64}$/;

/** The text written to Solana: a version tag, the night and the hash. No log content. */
export function memoText(nightId: string, hash: string): string {
  return `${MEMO_PREFIX}${nightId}:${hash}`;
}

/** Inverse of `memoText`, or null if the memo is not one of ours. */
export function parseMemo(text: string): { nightId: string; hash: string } | null {
  if (!text.startsWith(MEMO_PREFIX)) return null;
  const [nightId, hash, ...rest] = text.slice(MEMO_PREFIX.length).split(":");
  return { nightId, hash };
}
// Zod schemas and types for the `evidence` feature's tRPC inputs and outputs.
export { canonicalJson, memoText, parseMemo } from "./canonical";
export type { AnchorOutput, VerifyOutput } from "./schema";
export { anchorInput, anchorOutput, EVIDENCE_NOTE, verifyInput, verifyOutput } from "./schema";
import { z } from "zod";

export const anchorInput = z.object({ nightId: z.uuid() });
export const verifyInput = z.object({ nightId: z.uuid() });

const hex = z.string().regex(/^[0-9a-f]{64}$/);

export const EVIDENCE_NOTE = "Proves when the log existed, not that the noise happened.";

export const anchorOutput = z.object({
  nightId: z.uuid(),
  hash: hex,
  signature: z.string(),
  explorerUrl: z.string(),
  /** True when this log was already anchored and nothing new was written. */
  alreadyAnchored: z.boolean(),
});

/**
 * `not-anchored`: no memo yet. `match`: the log hashes to what the memo holds.
 * `mismatch`: the log was changed after it was anchored (or the memo is not for this night).
 */
export const verifyOutput = z.object({
  nightId: z.uuid(),
  status: z.enum(["not-anchored", "match", "mismatch"]),
  /** SHA-256 of the log as it is now */
  currentHash: hex,
  /** Hash read back from the on-chain memo */
  anchoredHash: hex.nullable(),
  signature: z.string().nullable(),
  explorerUrl: z.string().nullable(),
  /** What a match does and does not show. */
  note: z.string(),
});

export type AnchorOutput = z.infer<typeof anchorOutput>;
export type VerifyOutput = z.infer<typeof verifyOutput>;
